const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',program:'<path d="m12 2 4 4-4 4-4-4zm-6 6 4 4-4 4-4-4zm12 0 4 4-4 4-4-4zm-6 6 4 4-4 4-4-4z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0z"/><circle cx="12" cy="10" r="2"/>',play:'<path d="m9 5 11 7-11 7z"/>',feed:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="m10 8 5 4-5 4z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M8 8h8v8H8z"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',share:'<path d="m14 3 7 7-7 7v-5C7 12 4 15 3 20c0-10 5-14 11-14z"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',mute:'<path d="m11 4-6 5H2v6h3l6 5zM16 9l6 6m0-6-6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',down:'<path d="m5 9 7 7 7-7"/>',pause:'<path d="M8 5v14M16 5v14"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const tabs=[['home','Home','home'],['program','Program','program'],['agenda','My Agenda','clock'],['meetings','Meetings','people'],['map','Map','pin'],['feed','Feed','feed']];
let currentTab=location.hash==='#home'?'home':'feed';
const content=document.querySelector('#content');
function render(){observer?.disconnect();document.querySelectorAll('video').forEach(v=>v.pause());document.querySelector('.bottom-nav').innerHTML=tabs.map(([id,label,symbol])=>`<button class="nav-item ${currentTab===id?'active':''}" data-tab="${id}" ${!['home','feed'].includes(id)?'aria-disabled="true" title="Coming soon"':''} ${currentTab===id?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></button>`).join('');content.classList.toggle('feed-main',currentTab==='feed');content.innerHTML=currentTab==='feed'?feed():`<section class="welcome"><div><p class="eyebrow">WELCOME TO SLUSH</p><h1>Hello, Slusher<span style="color:var(--green)">.</span></h1><p class="subtext">The most founder-focused event on Earth.</p></div><span class="avatar large">AK</span></section><section class="home-feed-card"><img src="/media/4807.jpg" alt="A founder at work"><div><span class="pill">THE SLUSH FEED</span><h2>Big ideas.<br>Small screen.</h2><p>Meet the people behind the ideas.<br>One moment at a time.</p><button class="primary-button" data-tab="feed">Open the feed ${icon('play')}</button></div></section>`;document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));if(currentTab==='feed')initFeed();}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>el.classList.remove('visible'),2800)}
const clips=[
 {id:'4807',name:'The founder diaries',handle:'@slush',tag:'Behind the scenes',title:'It starts with an idea.',description:'A little glimpse of the work behind the pitch.',likes:128,credit:'stockyana',source:'https://mixkit.co/free-stock-video/woman-working-on-a-computer-in-a-boardroom-4807/'},
 {id:'4550',name:'Different perspectives',handle:'@slush',tag:'Community',title:'Good ideas belong to everyone.',description:'More voices. More perspectives. More possibilities.',likes:96,credit:'alona2018',source:'https://mixkit.co/free-stock-video/vlogger-recording-in-sign-language-4550/'},
 {id:'4603',name:'Better together',handle:'@slush',tag:'Startup life',title:'Nobody builds alone.',description:'Behind every big idea is a team making it happen.',likes:214,credit:'highwayvideography',source:'https://mixkit.co/free-stock-video/a-pair-of-employees-working-in-a-call-center-4603/'}
];
let preferences={liked:[],saved:[]};try{const p=JSON.parse(localStorage.getItem('slush-feed-preferences'));if(p&&Array.isArray(p.liked)&&Array.isArray(p.saved))preferences=p}catch{}
let observer,activeId=clips[0].id,muted=true,filter='all',resumeAfterDialog=false;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
function persist(){try{localStorage.setItem('slush-feed-preferences',JSON.stringify(preferences))}catch{}}
function visibleClips(){return filter==='saved'?clips.filter(c=>preferences.saved.includes(c.id)):clips}
function feed(){const visible=visibleClips();return `<div class="feed-layout"><aside class="feed-intro"><p class="eyebrow">THE MOMENTS IN BETWEEN</p><h1>Slush,<br>unfiltered<span>.</span></h1><p>Get a little closer to the people<br>and ideas moving things forward.</p><div class="feed-switch" aria-label="Feed filter"><button data-filter="all" class="${filter==='all'?'selected':''}" aria-pressed="${filter==='all'}">For you</button><button data-filter="saved" class="${filter==='saved'?'selected':''}" aria-pressed="${filter==='saved'}">Saved</button></div><div class="feed-instructions">${icon('feed')}<span>Scroll to discover.<br>Stay for the next idea.</span></div><button class="credits-link" data-action="credits">About these clips</button></aside><section class="feed-viewport" aria-label="Video feed" tabindex="0">${visible.length?visible.map((clip,i)=>`<article class="video-card" data-clip="${clip.id}" aria-label="${clip.name}"><video playsinline loop muted preload="${i===0?'auto':'metadata'}" poster="/media/${clip.id}.jpg" aria-label="${clip.name}" src="/media/${clip.id}.mp4"></video><div class="video-shade"></div><button class="video-tap" data-action="play" aria-label="Play video"><span class="center-play">${icon('play')}</span></button><div class="video-top"><span class="video-tag">${clip.tag}</span><button class="round-control sound-control" data-action="mute" aria-label="Unmute video">${icon('mute')}</button></div><div class="video-caption"><div class="creator"><span class="creator-avatar">S</span><div><strong>${clip.name}</strong><span>${clip.handle} <span class="verified">${icon('check')}</span></span></div></div><h2>${clip.title}</h2><p>${clip.description}</p><span class="clip-label">DEMO SERIES · ${String(i+1).padStart(2,'0')} / ${String(visible.length).padStart(2,'0')}</span></div><div class="video-actions"><button data-action="like" aria-label="Like video" aria-pressed="${preferences.liked.includes(clip.id)}" class="${preferences.liked.includes(clip.id)?'is-active':''}">${icon('heart')}<span>${clip.likes+(preferences.liked.includes(clip.id)?1:0)}</span></button><button data-action="save" aria-label="Save video" aria-pressed="${preferences.saved.includes(clip.id)}" class="${preferences.saved.includes(clip.id)?'is-active':''}">${icon('bookmark')}<span>Save</span></button><button data-action="share" aria-label="Share video">${icon('share')}<span>Share</span></button></div><div class="video-error" hidden><p>This video couldn’t load.</p><button class="outline-button" data-action="retry">Try again</button></div><div class="video-progress"><span></span></div></article>`).join(''):`<div class="feed-empty">${icon('bookmark')}<h2>Your next great find.</h2><p>Save a video to keep it here.</p><button class="primary-button" data-filter="all">Explore the feed</button></div>`}</section><aside class="feed-navigation"><span id="clip-counter">01 <em>/ ${String(visible.length).padStart(2,'0')}</em></span><div><button class="round-control" data-step="-1" aria-label="Previous video">${icon('down')}</button><button class="round-control" data-step="1" aria-label="Next video">${icon('down')}</button></div><span class="keyboard-hint">↑ ↓<br>to explore</span></aside></div>`}
function updatePlayback(video){const button=video.closest('.video-card').querySelector('.video-tap');button.classList.toggle('paused',video.paused);button.setAttribute('aria-label',video.paused?'Play video':'Pause video')}
function playVideo(video){if(!video)return;video.muted=muted;const result=video.play();if(result)result.catch(()=>updatePlayback(video))}
function initFeed(){const viewport=document.querySelector('.feed-viewport');const cards=[...viewport.querySelectorAll('.video-card')];observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{const video=entry.target.querySelector('video');if(entry.isIntersecting&&entry.intersectionRatio>.65){activeId=entry.target.dataset.clip;document.querySelectorAll('video').forEach(v=>{if(v!==video)v.pause()});if(!reducedMotion&&!document.hidden&&!document.querySelector('#modal').open)playVideo(video);updateCounter()}else video.pause()})},{root:viewport,threshold:[0,.65]});cards.forEach(card=>{const video=card.querySelector('video');observer.observe(card);video.addEventListener('play',()=>updatePlayback(video));video.addEventListener('pause',()=>updatePlayback(video));video.addEventListener('timeupdate',()=>{card.querySelector('.video-progress span').style.width=video.duration?`${video.currentTime/video.duration*100}%`:'0%'});video.addEventListener('error',()=>{card.querySelector('.video-error').hidden=false});updatePlayback(video)});const shared=location.hash.match(/^#feed\/(\d+)$/)?.[1];if(shared){const card=cards.find(c=>c.dataset.clip===shared);if(card){viewport.scrollTop=card.offsetTop;activeId=shared}}updateSound();updateCounter()}
function updateCounter(){const visible=visibleClips(),index=Math.max(0,visible.findIndex(c=>c.id===activeId));const counter=document.querySelector('#clip-counter');if(counter)counter.innerHTML=`${visible.length?String(index+1).padStart(2,'0'):'00'} <em>/ ${String(visible.length).padStart(2,'0')}</em>`;const prev=document.querySelector('[data-step="-1"]'),next=document.querySelector('[data-step="1"]');if(prev)prev.disabled=index===0;if(next)next.disabled=index>=visible.length-1}
function moveVideo(step){const visible=visibleClips(),index=visible.findIndex(c=>c.id===activeId),next=visible[index+step];if(next)document.querySelector(`[data-clip="${next.id}"]`).scrollIntoView({behavior:reducedMotion?'instant':'smooth',block:'nearest'})}
function updateSound(){document.querySelectorAll('video').forEach(v=>v.muted=muted);document.querySelectorAll('.sound-control').forEach(b=>{b.innerHTML=icon(muted?'mute':'sound');b.setAttribute('aria-label',muted?'Unmute video':'Mute video')})}
function navigate(tab){if(!['home','feed'].includes(tab)){toast('This tab is coming soon');return;}currentTab=tab;history.replaceState(null,'',`#${tab}`);render();window.scrollTo(0,0)}
function showModal(title,body){const v=document.querySelector(`[data-clip="${activeId}"] video`);resumeAfterDialog=!!v&&!v.paused;v?.pause();document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;document.querySelector('#modal').showModal()}
document.querySelector('#modal').addEventListener('close',()=>{if(resumeAfterDialog&&!document.hidden)playVideo(document.querySelector(`[data-clip="${activeId}"] video`))});
document.addEventListener('click',async event=>{const el=event.target.closest('button,a');if(!el)return;if(el.matches('.wordmark')){event.preventDefault();navigate('home');return}if(el.dataset.tab){document.querySelector('#modal').close();navigate(el.dataset.tab);return}if(el.dataset.filter){filter=el.dataset.filter;history.replaceState(null,'','#feed');render();return}if(el.dataset.step){moveVideo(Number(el.dataset.step));return}const action=el.dataset.action,card=el.closest('.video-card'),id=card?.dataset.clip,video=card?.querySelector('video');if(action==='play'){if(video.paused)playVideo(video);else video.pause()}if(action==='mute'){muted=!muted;updateSound()}if(action==='like'||action==='save'){const key=action==='like'?'liked':'saved',list=preferences[key],index=list.indexOf(id);if(index===-1)list.push(id);else list.splice(index,1);persist();el.classList.toggle('is-active',index===-1);el.setAttribute('aria-pressed',String(index===-1));if(action==='like')el.querySelector('span').textContent=clips.find(c=>c.id===id).likes+(index===-1?1:0);else{toast(index===-1?'Added to your saved videos':'Removed from saved videos');if(filter==='saved')render()}}if(action==='share'){const url=new URL(location.href);url.hash=`feed/${id}`;try{if(navigator.share)await navigator.share({title:clips.find(c=>c.id===id).title,url:url.href});else{await navigator.clipboard.writeText(url.href);toast('Video link copied')}}catch(error){if(error.name!=='AbortError')showModal('Share this moment',`<p>Copy this video’s link:</p><input class="share-url" aria-label="Video link" readonly value="${url.href.replaceAll('&','&amp;').replaceAll('"','&quot;')}">`)}}if(action==='retry'){card.querySelector('.video-error').hidden=true;video.load();playVideo(video)}if(action==='close')document.querySelector('#modal').close();if(action==='menu')showModal('Your Slush',`<button class="menu-row" data-tab="home">${icon('home')} Home ${icon('arrow')}</button><button class="menu-row" data-tab="feed">${icon('feed')} Feed ${icon('arrow')}</button><button class="menu-row" data-action="credits">About these clips ${icon('arrow')}</button>`);if(action==='notifications')showModal('You’re all caught up',`<p>No new notifications. Your next good idea might be one swipe away.</p><button class="primary-button full" data-tab="feed">Back to the feed</button>`);if(action==='profile'||action==='pass')showModal('Hello, Slusher.',`<div class="avatar">AK</div><p>Welcome to your Slush demo. Your likes and saved videos stay on this device.</p><button class="primary-button full" data-action="close">Keep exploring</button>`);if(action==='credits')showModal('About the feed',`<p>A demo of the Slush video experience, featuring sample clips from Mixkit. These are stock videos, not footage from Slush.</p>${clips.map(c=>`<a class="credit-row" href="${c.source}" target="_blank" rel="noopener noreferrer">${c.name}<span>Video by ${c.credit} ↗</span></a>`).join('')}<p>Likes and saves are stored on this device.</p>`)});
document.addEventListener('keydown',event=>{if(currentTab!=='feed'||document.querySelector('#modal').open||event.target.matches('input,textarea'))return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();moveVideo(event.key==='ArrowDown'?1:-1)}if(event.code==='Space'&&(event.target===document.body||event.target.classList.contains('feed-viewport'))){event.preventDefault();const video=document.querySelector(`[data-clip="${activeId}"] video`);if(video)video.paused?playVideo(video):video.pause()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause());else if(currentTab==='feed'&&!reducedMotion&&!document.querySelector('#modal').open)playVideo(document.querySelector(`[data-clip="${activeId}"] video`))});
window.addEventListener('hashchange',()=>{currentTab=location.hash==='#home'?'home':'feed';render()});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_slush',description:'Open the Home or Feed view in the Slush app.',inputSchema:{type:'object',properties:{tab:{type:'string',enum:['home','feed']}},required:['tab'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['home','feed'].includes(input.tab))throw Error('Choose home or feed');navigate(input.tab);return {tab:currentTab}}})).catch(()=>{})}catch{}}
render();
